// TestSerialWatchFlowJointE2E — serial-watch-flow box 7.1, the Tier-1 joint
// over the REAL composed graph (qa_playback_harness's pbWorld: real store,
// real serial-scanner SUBPROCESS, real api+web handler over real HTTP). A
// hermetic fixture serial library carries voiceover/subtitle sidecar
// subfolders — one voiceover file deleted after the scan — so the whole
// watch-flow chain runs across module joints with no mocks on any of them:
//
//   - sidecar facts: what the serial-scanner subprocess stamps at scan
//     (episode-linked audio+subtitle sidecars) survives to the served item
//     document (scan → store → API),
//   - sidecar serving: the media variant resolves the SUBTITLE bytes by the
//     document index the scan stamped (the same index space the descriptor's
//     voiceovers and the pack lane's derivation use), and answers 404
//     not_found for the absent voiceover — the fact resolves (index in
//     range), the file is gone, nothing leaks,
//   - descriptor voiceovers: GET /items/{id}/playback carries the audio
//     sidecars ON THE WIRE (the playbackResponse repair), in document order,
//     labeled language-then-folder, subtitles never projected, and the fetch
//     mutates no packaging state,
//   - title override: PUT → record echo → DTO read → DELETE → cleared, over
//     BOTH real id spaces (the scanned series and its episode), which share
//     the store's override table.
//
// The absent voiceover does NOT drop off the descriptor: the projection reads
// stored facts only (packaged-playback spec "Voiceover tracks on the playback
// descriptor" — never a re-probe); the resolvable-only gate lives in the
// media variant's file open (asserted here as the 404) and in the pack lane's
// build-time soft-omit (unit-pinned by TestPackRenditions). The expected
// values are re-derived independently of the plugin suites' fixtures (different
// show/subfolder names) so a hard-coded value in the shipped code cannot pass
// by coincidence.
package itest

import (
	"encoding/json"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"
	"time"
)

// Fixture identity — one serial directory whose sidecars sit in dedicated
// subfolders: two voiceover audio tracks (Jpn/Rus language folders) and one
// subtitle. All three stems carry the episode's SxxExx token, so all three
// associate episode-linked ("sxxexx"); "Subs" is deliberately NOT a language
// folder (the ground-truth SUB convention), so the subtitle keeps an empty
// language.
const (
	swfDir    = "Watch Flow Show S01 (QA)"
	swfEpBase = "Watch Flow Show S01E01.mkv"
	swfEpRel  = swfDir + "/" + swfEpBase
	swfJpnRel = swfDir + "/Jpn/Watch Flow Show S01E01.mka"
	swfRusRel = swfDir + "/Rus/Watch Flow Show S01E01.mka"
	swfSubRel = swfDir + "/Subs/Watch Flow Show S01E01.srt"
)

var swfSubtitleBytes = []byte("1\n00:00:00,000 --> 00:00:01,000\nwatch-flow joint fixture line\n")

// swfSidecarFact / swfItemDoc decode the scan-stamped document slices the
// assertions navigate (black box: api-local shapes are not imported).
type swfSidecarFact struct {
	RelativePath string  `json:"relative_path"`
	Kind         string  `json:"kind"`
	Language     string  `json:"language"`
	MatchBasis   *string `json:"match_basis"`
}

type swfItemDoc struct {
	Parsed struct {
		AbsolutePath       string           `json:"absolute_path"`
		SeriesRelativePath string           `json:"series_relative_path"`
		Sidecars           []swfSidecarFact `json:"sidecars"`
	} `json:"parsed"`
}

// swfDescriptor is the descriptor wire shape with the voiceover projection
// (the pbPlayback harness decode predates the wire repair and carries no
// voiceovers field, so this test decodes its own).
type swfDescriptor struct {
	Mode       string           `json:"mode"`
	State      string           `json:"state"`
	PlayURL    string           `json:"play_url"`
	Voiceovers []map[string]any `json:"voiceovers"`
}

// swfTitleCarrier reads title_override off a detail DTO; swfTitleRecord is the
// PUT 200 body; the two envelopes decode the {item:|series:{...}} detail
// shapes.
type swfTitleCarrier struct {
	TitleOverride string `json:"title_override"`
}

type swfTitleRecord struct {
	EntityID  string `json:"entity_id"`
	Title     string `json:"title"`
	UpdatedAt string `json:"updated_at"`
}

type swfItemEnvelope struct {
	Item struct {
		ID            string          `json:"id"`
		Document      json.RawMessage `json:"document"`
		TitleOverride string          `json:"title_override"`
	} `json:"item"`
}

type swfSeriesEnvelope struct {
	Series struct {
		ID            string `json:"id"`
		RelativePath  string `json:"relative_path"`
		TitleOverride string `json:"title_override"`
	} `json:"series"`
}

// swfSidecarIndex returns the document index of one sidecar relative path.
func swfSidecarIndex(t *testing.T, doc swfItemDoc, rel string) int {
	t.Helper()
	for i, sc := range doc.Parsed.Sidecars {
		if sc.RelativePath == rel {
			return i
		}
	}
	t.Fatalf("sidecar %q not in the episode document: %+v", rel, doc.Parsed.Sidecars)
	return -1
}

// swfDetailTitle fetches a detail view and returns its title_override.
func swfDetailTitle(t *testing.T, w *pbWorld, url string) string {
	t.Helper()
	var env swfItemEnvelope
	if status := doRequest(t, w.client, http.MethodGet, url, w.token, nil, &env); status != http.StatusOK {
		t.Fatalf("GET %s: status %d, want 200", url, status)
	}
	return env.Item.TitleOverride
}

// swfPutTitle / swfDeleteTitle drive one title route half of the round-trip:
// PUT asserts the 200 record echo, DELETE asserts the idempotent 204.
func swfPutTitle(t *testing.T, w *pbWorld, url, title, wantEntity string) {
	t.Helper()
	var rec swfTitleRecord
	status := doRequest(t, w.client, http.MethodPut, url, w.token, map[string]string{"title": title}, &rec)
	if status != http.StatusOK {
		t.Fatalf("PUT %s: status %d, want 200", url, status)
	}
	if rec.EntityID != wantEntity || rec.Title != title || rec.UpdatedAt == "" {
		t.Fatalf("PUT %s record = %+v, want entity %q title %q and a non-empty stamp", url, rec, wantEntity, title)
	}
}

func swfDeleteTitle(t *testing.T, w *pbWorld, url string) {
	t.Helper()
	if status := doRequest(t, w.client, http.MethodDelete, url, w.token, nil, nil); status != http.StatusNoContent {
		t.Fatalf("DELETE %s: status %d, want 204", url, status)
	}
}

// TestSerialWatchFlowJointE2E is the serial-watch-flow acceptance floor: one
// fixture library through the real scan, then the four joint behaviors over
// the real HTTP surface.
func TestSerialWatchFlowJointE2E(t *testing.T) {
	w := pbNewWorld(t)

	// The hermetic fixture: one serial directory, one probeable episode,
	// voiceover audio in Jpn/ and Rus/ subfolders, the subtitle in Subs/.
	libRoot := t.TempDir()
	dirAbs := filepath.Join(libRoot, swfDir)
	mustMkdir(t, dirAbs)
	pbMakeMKV(t, filepath.Join(dirAbs, swfEpBase), 2*time.Second, false)
	mustMkdir(t, filepath.Join(dirAbs, "Jpn"))
	mustMkdir(t, filepath.Join(dirAbs, "Rus"))
	mustMkdir(t, filepath.Join(dirAbs, "Subs"))
	mustWrite(t, filepath.Join(libRoot, swfJpnRel), []byte("jpn voiceover"))
	mustWrite(t, filepath.Join(libRoot, swfRusRel), []byte("rus voiceover"))
	mustWrite(t, filepath.Join(libRoot, swfSubRel), swfSubtitleBytes)

	// The real scan: serial-scanner subprocess + real ffprobe over the real
	// HTTP handler. Exactly 2 discoveries (the serial record + the episode);
	// the sidecar subfolders leak no items and warn about nothing.
	libID := pbCreateLibrary(t, w, "serial", libRoot, "QA Serial Watch Flow")
	res := pbScanLibrary(t, w, libID)
	if res.Discovered != 2 || res.Persisted != 2 {
		t.Fatalf("scan discovered=%d persisted=%d, want 2/2 (1 serial record + 1 episode; sidecars never items); warnings=%v",
			res.Discovered, res.Persisted, res.Warnings)
	}
	if len(res.Warnings) != 0 {
		t.Fatalf("scan warnings = %v, want none (clean fixture)", res.Warnings)
	}
	items := pbItemByRel(t, w, libID)
	ep, ok := items[swfEpRel]
	if !ok {
		t.Fatalf("episode %q not persisted; have %v", swfEpRel, qaSerialMapKeys(items))
	}
	seriesList := qaSerialListSeries(t, w.client, w.baseURL, w.token, libID)
	if len(seriesList) != 1 || seriesList[0].RelativePath != swfDir {
		t.Fatalf("series = %+v, want exactly %q", seriesList, swfDir)
	}
	sid := seriesList[0].ID

	// THE ABSENT VOICEOVER: the scan has stamped the Rus fact into the
	// document; the file is now gone from disk. Every assertion below reads
	// the persisted document, not the disk.
	if err := os.Remove(filepath.Join(libRoot, swfRusRel)); err != nil {
		t.Fatalf("remove the Rus voiceover fixture: %v", err)
	}

	var doc swfItemDoc
	if err := json.Unmarshal(ep.Document, &doc); err != nil {
		t.Fatalf("decode episode document: %v", err)
	}
	jpnIdx := swfSidecarIndex(t, doc, swfJpnRel)
	rusIdx := swfSidecarIndex(t, doc, swfRusRel)
	subIdx := swfSidecarIndex(t, doc, swfSubRel)
	itemTitleURL := w.baseURL + "/api/v1/items/" + ep.ID + "/title"
	seriesTitleURL := w.baseURL + "/api/v1/series/" + sid + "/title"

	t.Run("episode_documents_carry_sidecar_facts", func(t *testing.T) {
		if ep.MediaType != "serial" {
			t.Errorf("media_type = %q, want serial", ep.MediaType)
		}
		if doc.Parsed.SeriesRelativePath != swfDir {
			t.Errorf("parsed.series_relative_path = %q, want %q", doc.Parsed.SeriesRelativePath, swfDir)
		}
		if want := filepath.Join(libRoot, swfEpRel); doc.Parsed.AbsolutePath != want {
			t.Errorf("parsed.absolute_path = %q, want %q (the derivation root the sidecar serving shares)", doc.Parsed.AbsolutePath, want)
		}
		// Exactly the three stamped facts, in the scanner's document order
		// (sorted by relative path), each episode-linked by SxxExx.
		if len(doc.Parsed.Sidecars) != 3 {
			t.Fatalf("parsed.sidecars = %+v, want exactly 3 entries", doc.Parsed.Sidecars)
		}
		for i, want := range []swfSidecarFact{
			{RelativePath: swfJpnRel, Kind: "audio", Language: "Jpn", MatchBasis: strPtr("sxxexx")},
			{RelativePath: swfRusRel, Kind: "audio", Language: "Rus", MatchBasis: strPtr("sxxexx")},
			{RelativePath: swfSubRel, Kind: "subtitle", Language: "", MatchBasis: strPtr("sxxexx")},
		} {
			got := doc.Parsed.Sidecars[i]
			if got.RelativePath != want.RelativePath || got.Kind != want.Kind || got.Language != want.Language {
				t.Errorf("sidecars[%d] = %+v, want %+v", i, got, want)
			}
			if want.MatchBasis == nil {
				if got.MatchBasis != nil {
					t.Errorf("sidecars[%d].match_basis = %q, want JSON null", i, *got.MatchBasis)
				}
			} else if got.MatchBasis == nil || *got.MatchBasis != *want.MatchBasis {
				t.Errorf("sidecars[%d].match_basis = %v, want %q", i, got.MatchBasis, *want.MatchBasis)
			}
		}
	})

	t.Run("sidecar_variant_serves_indexed_subtitle", func(t *testing.T) {
		// The subtitle serves byte-exact at its DOCUMENT index — the same
		// index space the descriptor's voiceovers carry below (D-4: a number
		// into the stored list, never a client path).
		url := w.baseURL + "/api/v1/items/" + ep.ID + "/media?variant=sidecar&n=" + strconv.Itoa(subIdx)
		status, body, _ := pbDo(t, w.client, http.MethodGet, url, w.token, nil)
		if status != http.StatusOK {
			t.Fatalf("sidecar media n=%d: status %d, want 200 (body=%s)", subIdx, status, body)
		}
		if string(body) != string(swfSubtitleBytes) {
			t.Fatalf("sidecar media n=%d served %q, want the subtitle bytes %q", subIdx, body, swfSubtitleBytes)
		}
		// The absent voiceover: the fact resolves (rusIdx is in range) but the
		// file is gone — 404 not_found, no path leak, no fabricated bytes.
		url = w.baseURL + "/api/v1/items/" + ep.ID + "/media?variant=sidecar&n=" + strconv.Itoa(rusIdx)
		status, body, _ = pbDo(t, w.client, http.MethodGet, url, w.token, nil)
		if status != http.StatusNotFound {
			t.Fatalf("absent voiceover n=%d: status %d, want 404 (body=%s)", rusIdx, status, body)
		}
	})

	t.Run("descriptor_lists_voiceovers", func(t *testing.T) {
		status, body, _ := pbDo(t, w.client, http.MethodGet, w.baseURL+"/api/v1/items/"+ep.ID+"/playback", w.token, nil)
		if status != http.StatusOK {
			t.Fatalf("descriptor: status %d, want 200 (body=%s)", status, body)
		}
		var desc swfDescriptor
		if err := json.Unmarshal(body, &desc); err != nil {
			t.Fatalf("decode descriptor: %v (body=%s)", err, body)
		}
		// No pack ran: the direct floor stands and the fetch changed no
		// packaging state.
		if desc.Mode != "direct" || desc.State != "none" {
			t.Fatalf("descriptor = mode %q state %q, want direct/none (nothing packed)", desc.Mode, desc.State)
		}
		if !strings.HasPrefix(desc.PlayURL, "/media/") {
			t.Errorf("play_url = %q, want the /media direct floor", desc.PlayURL)
		}
		// The audio sidecars project ON THE WIRE (the playbackResponse
		// repair), in document order, language-first labels, with their
		// document indexes — including the absent Rus file (stored facts
		// only, never a re-probe). The subtitle never projects.
		if len(desc.Voiceovers) != 2 {
			t.Fatalf("voiceovers = %v, want exactly the two audio sidecars", desc.Voiceovers)
		}
		for i, want := range []struct {
			index int
			label string
		}{{jpnIdx, "Jpn"}, {rusIdx, "Rus"}} {
			got := desc.Voiceovers[i]
			idx, _ := got["index"].(float64)
			label, _ := got["label"].(string)
			if int(idx) != want.index || label != want.label {
				t.Errorf("voiceovers[%d] = %v, want {index:%d label:%q}", i, got, want.index, want.label)
			}
		}
		// The fetches wrote nothing: the stored document still carries no
		// streams namespace (read-only descriptor).
		var fresh swfItemEnvelope
		if status := doRequest(t, w.client, http.MethodGet, w.baseURL+"/api/v1/items/"+ep.ID, w.token, nil, &fresh); status != http.StatusOK {
			t.Fatalf("re-read item: status %d, want 200", status)
		}
		var after map[string]any
		if err := json.Unmarshal(fresh.Item.Document, &after); err != nil {
			t.Fatalf("decode re-read document: %v", err)
		}
		if _, leaked := after["streams"]; leaked {
			t.Errorf("descriptor fetch minted a streams namespace: %v", after["streams"])
		}
	})

	t.Run("title_override_roundtrip", func(t *testing.T) {
		// The episode space: PUT → record echo → the detail DTO carries the
		// override → DELETE → cleared (the tolerant lookup's empty wire field).
		swfPutTitle(t, w, itemTitleURL, "Watch Flow Episode (Renamed)", ep.ID)
		if got := swfDetailTitle(t, w, w.baseURL+"/api/v1/items/"+ep.ID); got != "Watch Flow Episode (Renamed)" {
			t.Errorf("item title_override after PUT = %q, want the override", got)
		}
		// The series space — a different id space sharing the same override
		// table — round-trips independently against the scanned serial row.
		swfPutTitle(t, w, seriesTitleURL, "Watch Flow Show (Renamed)", sid)
		var senv swfSeriesEnvelope
		if status := doRequest(t, w.client, http.MethodGet, w.baseURL+"/api/v1/series/"+sid, w.token, nil, &senv); status != http.StatusOK {
			t.Fatalf("GET series: status %d, want 200", status)
		}
		if senv.Series.TitleOverride != "Watch Flow Show (Renamed)" {
			t.Errorf("series title_override after PUT = %q, want the override", senv.Series.TitleOverride)
		}
		// Clear both; the override tier leaves the chain exactly as it was.
		swfDeleteTitle(t, w, itemTitleURL)
		swfDeleteTitle(t, w, seriesTitleURL)
		if got := swfDetailTitle(t, w, w.baseURL+"/api/v1/items/"+ep.ID); got != "" {
			t.Errorf("item title_override after DELETE = %q, want empty", got)
		}
		if status := doRequest(t, w.client, http.MethodGet, w.baseURL+"/api/v1/series/"+sid, w.token, nil, &senv); status != http.StatusOK {
			t.Fatalf("re-GET series: status %d, want 200", status)
		}
		if got := senv.Series.TitleOverride; got != "" {
			t.Errorf("series title_override after DELETE = %q, want empty", got)
		}
	})
}

// strPtr is a tiny literal helper for the match_basis expectations.
func strPtr(s string) *string { return &s }
